/// <summary>
/// COC extension class for <c>FreeTextInvoice</c> class 
/// </summary>

[ExtensionOf(classStr(FreeTextInvoiceDP))]
final class METFreeTextInvoiceDP_Extension
{
    public METRebateInvoiceDetailsTmp metRebateInvoiceDetailsTmp;
    public TAMRebateDeal rebateDeal;
    public TAMRebateDateTrans rebateDateTrans;
    private boolean isFTIRebateCheckDone;
    private boolean isthisFTIRebate;
    public boolean areRebatedetailsCreated;

}

