/// <summary>
///    Fetches the data from the temporary <c>CustInterestNoteTmp</c> table.
/// </summary>
/// <returns>
///    The data in the <c>FreeTextInvoiceTmp</c> table.
/// </returns>
[SRSReportDataSet(tableStr(METRebateInvoiceDetailsTmp))]
public METRebateInvoiceDetailsTmp getFreeTextRebateInvoiceDetailsTmp()
{
    select metRebateInvoiceDetailsTmp;
    return metRebateInvoiceDetailsTmp;
}

/// <summary>
/// For the table to be linked to current user connection or session.
/// </summary>
public void setTableConnections()
{
    next setTableConnections();

    metRebateInvoiceDetailsTmp.setConnection(this.parmUserConnection());
}

/// <summary>
/// Populates the invoice header information into the <c>FreeTextInvoiceHeaderFooterTmp</c> table buffer.
/// </summary>
/// <param name="_custInvoiceJour">
/// The <c>CustInvoiceJour</c> record that has the invoice header information.
/// </param>
/// <param name="_companyInfo">
/// The <c>CompanyInfo</c> record that has the company information.
/// </param>
protected void populateFreeTextInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, CompanyInfo _companyInfo)
{
    next populateFreeTextInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);

    if (this.checkFreeTextInvoiceAsRebate(_custInvoiceJour))
    {
        this.populateRebateInvoiceHeaderDetails(_custInvoiceJour);
    }

}

/// <summary>
/// Initalise rebate related information in header temparory table for FreeTextInvoice - Volumentric or Non Volumetric Rebate Invoice report.
/// </summary>
protected void populateRebateInvoiceHeaderDetails(CustInvoiceJour _custInvoiceJour)
{
    FiscalCalendarPeriod    fiscalCalendarPeriod;
    FiscalCalendar          fiscalCal;
    FiscalCalendarYear      fiscalCalYear;
    FiscalCalendarID        calendarId = FiscalCalendar::find(Ledger::fiscalCalendar(CompanyInfo::current())).CalendarId;

    CustInvoiceTable custInvoiceTable   = _custInvoiceJour.custInvoiceTable();
    CustAccount custAccount;
    InventLocation inventLocation;
    CustTable custTable;

    if (!custInvoiceTable || _custInvoiceJour.isProforma())
    {
        // custInvoiceJour.InvoiceId is # + Recid so we must strip the leading #
        select custInvoiceTable
            where custInvoiceTable.RecId == str2int64(subStr(_custInvoiceJour.InvoiceId, 2, strLen(_custInvoiceJour.InvoiceId)));

        custAccount = _custInvoiceJour.InvoiceAccount;
    }
    else
    {
        custAccount = custInvoiceTable.InvoiceAccount;
    }

    METCustTable metCustTable = METCustTable::find(custAccount);
    METIndustryKeyTable industryKeyTable  = METIndustryKeyTable::find(metCustTable.IndustryKey);

    select firstonly RebateId, RebateFromDate, RebateToDate, RebateDeal from rebateDateTrans
        where rebateDateTrans.RebateTransId == custInvoiceTable.TAMRebateTransId
    join METVolumetricTierDeal, RebateDocumentNotes, Deal from rebateDeal
        where rebateDeal.RecId == rebateDateTrans.RebateDeal;

    METIndustryKey industryKey = metCustTable.IndustryKey;
    FreeTextInvoiceContract freeTextInvoiceContract = this.parmDataContract() as FreeTextInvoiceContract;
    SRSCatalogItemName reportNameLocal = freeTextInvoiceContract.parmMETSelectedReportName();

    if (reportNameLocal && industryKey)
    {
        container reportDesignNameContainer = SrsReportRunUtil::getReportAndDesignName(reportNameLocal);
        SysDocuBrandDetails docuBrandDetails = SysDocuBrandDetails::findByRepNameAndIndKey(conPeek(reportDesignNameContainer, 1), conPeek(reportDesignNameContainer, 2), industryKey);

        freeTextInvoiceHeaderFooterTmp.METIndustryKey = industryKey;
        freeTextInvoiceHeaderFooterTmp.CompanyName = industryKeyTable.CompanyName;

        if (docuBrandDetails)
        {
            freeTextInvoiceHeaderFooterTmp.CompanyCoRegNum = docuBrandDetails.METTaxRegNumber;
            // Task 226480: Branding details update - Reports - Start
            // freeTextInvoiceHeaderFooterTmp.CompanyLogo     = SysDocuBrandImages::getImage(docuBrandDetails.Image1Name);
            // Task 226480: Branding details update - Reports - End
            freeTextInvoiceHeaderFooterTmp.CompanyEmail    = docuBrandDetails.Email;
            freeTextInvoiceHeaderFooterTmp.CompanyPhone    = docuBrandDetails.Phone;
            freeTextInvoiceHeaderFooterTmp.CompanyTeleFax  = docuBrandDetails.TeleFax;
        }
    }
    // Task 226480: Branding details update - Reports - Start
    freeTextInvoiceHeaderFooterTmp.METTAMRebateTransId = custInvoiceTable.TAMRebateTransId;
    freeTextInvoiceHeaderFooterTmp.METVolumetricTierDeal = custInvoiceTable.METVolumetricTierDeal;
    // Task 226480: Branding details update - Reports - End
    freeTextInvoiceHeaderFooterTmp.METInvoiceNumber = custInvoiceTable.InvoiceId;
    freeTextInvoiceHeaderFooterTmp.InvoiceDate      = custInvoiceTable.InvoiceDate;

    select firstonly Name from inventLocation
        exists join custTable
            where custTable.InventLocation == inventLocation.InventLocationId
                && custTable.AccountNum == custInvoiceTable.OrderAccount;

    freeTextInvoiceHeaderFooterTmp.METBranch        = inventLocation.Name;
    freeTextInvoiceHeaderFooterTmp.METRebateName    = rebateDeal.Description;
    freeTextInvoiceHeaderFooterTmp.METFromPeriod    = rebateDateTrans.RebateFromDate;
    freeTextInvoiceHeaderFooterTmp.METToPeriod      = rebateDateTrans.RebateToDate;

    freeTextInvoiceHeaderFooterTmp.METInvoiceToName = custInvoiceTable.custTable_OrderAccount().DirPartyTable_FK().KnownAs;

    LogisticsLocationRoleRecId invoiceRoleRecId = LogisticsLocationRole::findByName(METConstants::InvoiceRole).RecId;
    RefRecId party = custInvoiceTable.custTable_OrderAccount().Party;
    DirPartyPostalAddressView dirPartyPostalAddressView = this.getCustomerAddressByInvoice(party, DirPartyTable::findRec(party).PrimaryAddressLocation, invoiceRoleRecId);

    /*freeTextInvoiceHeaderFooterTmp.METInvoiceToAddress = dirPartyPostalAddressView.Street + METConstants::NextLine
                                            + dirPartyPostalAddressView.City + METConstants::NextLine
                                            + dirPartyPostalAddressView.State + METConstants::NextLine
                                            + dirPartyPostalAddressView.ZipCode + METConstants::NextLine
                                            + dirPartyPostalAddressView.CountryRegionId; */
    CustTable custtableloc = CustTable::find(custInvoiceTable.OrderAccount);
    freeTextInvoiceHeaderFooterTmp.METInvoiceToAddress = custtableloc.invoiceAddress().Address;//BUG 256454

    freeTextInvoiceHeaderFooterTmp.METInvoiceToCustNumber = custInvoiceTable.custTable_OrderAccount().AccountNum;
    freeTextInvoiceHeaderFooterTmp.METRebateNote          = rebateDeal.RebateDocumentNotes;

    if (rebateDeal.METVolumetricTierDeal)
    {
        select firstonly METNoOfWeeksForPeriod from fiscalCalendarPeriod
        exists join fiscalCalYear
            where fiscalCalendarPeriod.FiscalCalendarYear == fiscalCalYear.RecId
        exists join fiscalCal
            where fiscalCal.RecId == fiscalCalYear.FiscalCalendar
            && fiscalCal.CalendarId == calendarId
            && fiscalCalendarPeriod.Type == FiscalPeriodType::Operating
            && fiscalCalendarPeriod.StartDate == rebateDateTrans.RebateFromDate
            && fiscalCalendarPeriod.EndDate == rebateDateTrans.RebateToDate;

        freeTextInvoiceHeaderFooterTmp.METNoOfWeeksForPeriod = fiscalCalendarPeriod.METNoOfWeeksForPeriod;
    }
}

/// <summary>
/// Populates the Invoice details information into the <c>FreeTextInvoiceTmp</c> table buffer.
/// </summary>
/// <param name="_custInvoiceJour">
/// The <c>CustInvoiceJour</c> record that has the invoice header information.
/// </param>
/// <param name="_custInvoiceTrans">
/// The <c>CustInvoiceTrans</c> record that has the invoice details information.
/// </param>
/// <param name="_taxSpec">
/// The <c>TaxSpec</c> class instance that has the taxes information.
/// </param>
/// <param name="_custPaymSchedLine">
/// The <c>CustPaymSchedLine</c> record that has the payment schedules information.
/// </param>
/// <param name="_prepaymentCustTrans">
/// The <c>CustTrans</c> record that has the prepayment information.
/// </param>
/// <param name="_prepaymentTaxTrans">
/// The <c>TaxTrans</c> record that has the prepayment taxes information.
/// </param>
protected void populateFreeTextInvoiceTmp(
    CustInvoiceJour _custInvoiceJour,
    CustInvoiceTrans _custInvoiceTrans,
    TaxSpec _taxSpec,
    CustPaymSchedLine _custPaymSchedLine,
    CustTrans _prepaymentCustTrans,
    TaxTrans _prepaymentTaxTrans)
{
    next populateFreeTextInvoiceTmp(
        _custInvoiceJour,
        _custInvoiceTrans,
        _taxSpec,
        _custPaymSchedLine,
        _prepaymentCustTrans,
        _prepaymentTaxTrans);

    if (this.checkFreeTextInvoiceAsRebate(_custInvoiceJour))
    {
        if (!areRebatedetailsCreated)
        {
            areRebatedetailsCreated = true;
            this.populateRebateInvoiceDetails(_custInvoiceJour, _custInvoiceTrans);
        }
    }
}

/// <summary>
/// Creates a <c>RebateInvoiceLinesrTmp</c> record.
/// </summary>
protected void populateRebateInvoiceDetails(CustInvoiceJour _custInvoiceJour, CustInvoiceTrans _custInvoiceTrans)
{
    CustInvoiceLine custInvoiceLine;
    METTierRateTrans metTierRateTrans;
    TAMRebateTrans tamRebateTransSummed;
    CustInvoiceLine custInvoiceLineSummed;

    TAMRebateLine tamRebateLine;
    TAMRebateTable tamRebateTable;

    RecordInsertList rebateInvoiceLineTmpList = new RecordInsertList(tableNum(METRebateInvoiceDetailsTmp));

    CustInvoiceTable custInvoiceTable = _custInvoiceJour.custInvoiceTable();

    if (rebateDeal.METVolumetricTierDeal)
    {
        // For Average weekly sales and 
        select firstonly AgEligibleTransAmount, EligibleRebate, WeeklyAverage from metTierRateTrans
            where metTierRateTrans.TAMRebateDealId        == rebateDeal.Deal
                && metTierRateTrans.FromDate              == rebateDateTrans.RebateFromDate
                && metTierRateTrans.ToDate                == rebateDateTrans.RebateToDate
                && metTierRateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate;
    }
    else
    {   
        //For Rate
        select firstonly RebateAmount from tamRebateLine
        exists join tamRebateTable
            where tamRebateLine.RebateId == tamRebateTable.RebateId
                && tamRebateTable.RebateDeal == rebateDeal.RecId
                && tamRebateLine.RebateFrom  <= rebateDateTrans.RebateAmount
                && tamRebateLine.RebateLimit >= rebateDateTrans.RebateAmount
                && tamRebateLine.METTierLineType == METTierLineType::Rate;
    }

    while select sum(AmountCur), Description, TaxItemGroup, TaxGroup from custInvoiceLine
        group by Description, TaxItemGroup, TaxGroup
            where custInvoiceLine.ParentRecId == custInvoiceTable.RecId
    {
        //For Eligible sales value grouped as per Item type/ Invoice line description.
        //Source transactions- 'Invoice Amount' to be summed based on Commodity group/Item types.
        select firstonly sum(RebateRefAmount) from tamRebateTransSummed
            group by RebateTransId , METTaxItemGroup, MetItemTypes, METItemTypeDescription
                where tamRebateTransSummed.RebateTransId == custInvoiceTable.TAMRebateTransId
                    && tamRebateTransSummed.METItemTypeDescription == custInvoiceLine.Description //Not holding METItemTypes in CustInvoiceLine table, instead storing its description.
                    && tamRebateTransSummed.METTaxItemGroup == custInvoiceLine.TaxItemGroup;

        //For Total Rebate value grouped invoice lines as per Description and Parent record(CustInvoiceTable)
        //Free text invoice lines -  Amount summed bases on Commodity group/Item types.
        select firstonly sum(AmountCur), Description, TaxItemGroup, ParentRecId from custInvoiceLineSummed
            group by Description, TaxItemGroup, ParentRecId
                where custInvoiceLineSummed.Description == custInvoiceLine.Description
                    && custInvoiceLineSummed.TaxItemGroup == custInvoiceLine.TaxItemGroup
                    && custInvoiceLineSummed.ParentRecId == custInvoiceTable.RecId;

        metRebateInvoiceDetailsTmp.CommodityGroup = (custInvoiceLine.TaxItemGroup == METConstants::taxGroupGSTFree || custInvoiceLine.TaxItemGroup == METConstants::GSTFree)
                                                    ? custInvoiceLine.Description + METConstants::space + custInvoiceLine.TaxItemGroup
                                                    : custInvoiceLine.Description;
        metRebateInvoiceDetailsTmp.EligibleSales  = tamRebateTransSummed.RebateRefAmount;
        metRebateInvoiceDetailsTmp.TotalRebate    = trunc(custInvoiceLineSummed.AmountCur*100)/100;  //Truncating the value to 2 decimal places as requested in Bug_288237.
        metRebateInvoiceDetailsTmp.GST            = this.getGSTAmountForCommodityGroup(custInvoiceLine.Description, custInvoiceLine.TaxItemGroup, custInvoiceTable);
        metRebateInvoiceDetailsTmp.TotalIncGST    = metRebateInvoiceDetailsTmp.TotalRebate + metRebateInvoiceDetailsTmp.GST;

        if (rebateDeal.METVolumetricTierDeal)
        {
            metRebateInvoiceDetailsTmp.Rate                 = metTierRateTrans.EligibleRebate;
            metRebateInvoiceDetailsTmp.AverageWeeklySales   = metTierRateTrans.WeeklyAverage;
        }
        else
        {
            metRebateInvoiceDetailsTmp.Rate                 = tamRebateLine.RebateAmount;
        }

        rebateInvoiceLineTmpList.add(metRebateInvoiceDetailsTmp);
    }

    rebateInvoiceLineTmpList.insertDatabase();
}

/// <summary>
/// Get customer address by Invoice Purpose
/// </summary>
/// <param name = "_party">DirPartyRecid</param>
/// <param name = "_locationRecId">LocationRecId</param>
/// <param name = "_invoiceRoleRecId">InvoiceRoleRecId</param>
/// <returns>Address</returns>
public DirPartyPostalAddressView getCustomerAddressByInvoice(RefRecId _party, LogisticsLocationRecId _locationRecId, LogisticsLocationRoleRecId _invoiceRoleRecId)
{
    DirPartyPostalAddressView   dirPartyPostalAddressView;
    DirPartyLocationRole        dirPartyLocationRole;

    select firstonly dirPartyPostalAddressView
        where dirPartyPostalAddressView.Party == _party
        && dirPartyPostalAddressView.Location == _locationRecId
        && dirPartyPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && dirPartyPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
    exists join dirPartyLocationRole
        where dirPartyLocationRole.PartyLocation == dirPartyPostalAddressView.RecId
        && dirPartyLocationRole.LocationRole == _invoiceRoleRecId;

    return dirPartyPostalAddressView;

}

/// <summary>
/// Method to determine the FTI report generated for FTI transaction is related to Rebate. 
/// If so, this method avoid the unnecessary assignment or initialization occruing in KPMGFreeTextInvoiceDP_extension class.
/// </summary>
/// <param name = "_custInvoiceJour">Buffer of CustInvoiceJour</param>
/// <returns>Boolean True for FTI related to a rebate deal transaction Id, else false</returns>
public boolean checkFreeTextInvoiceAsRebate(CustInvoiceJour _custInvoiceJour)
{
    if (!isFTIRebateCheckDone)
    {
        CustInvoiceTable custInvoiceTable;

        if (_custInvoiceJour.isProforma())
        {
            // custInvoiceJour.InvoiceId is # + Recid so we must strip the leading #
            select custInvoiceTable
                where custInvoiceTable.RecId == str2int64(subStr(_custInvoiceJour.InvoiceId, 2, strLen(_custInvoiceJour.InvoiceId)));
        }
        else
        {
            custInvoiceTable = _custInvoiceJour.custInvoiceTable();
        }

        if (custInvoiceTable.TAMRebateTransId)
        {
            isthisFTIRebate = true;

            //An additional check to determine other than above if the FTI is linked to rebate.
            FreeTextInvoiceContract contractLocal = this.parmDataContract();
            if (contractLocal.parmMETSelectedReportName() == ssrsReportStr(METFreeTextInvoiceRebate, Report)) //Task 226480: Branding details update - Reports
            {
                isthisFTIRebate = true;
            }
            else
            {
                isthisFTIRebate = false;
            }
        }

        isFTIRebateCheckDone = true;
    }

    return isthisFTIRebate;
}

/// <summary>
/// Method used to calculated the GST tax amount for free text invoice lines of similar description as Item types or commodity group for report lines.
/// </summary>
/// <param name = "_description">Invoice line description. At times could be a blank description too</param>
/// <param name = "_taxItemgroup">Item GST group from the Free text invoice line</param>
/// <param name = "_custTableInvoice">CustInvoiceTable table buffer</param>
/// <returns>A summed GST amount for similar Commodity group</returns>
public Amount getGSTAmountForCommodityGroup(Description _description, TaxItemGroup _taxItemgroup, CustInvoiceTable _custInvoiceTable)
{
    TaxAmountCur summedGSTTaxAmount;
    CustInvoiceLine custInvoiceLine;

    if (_taxItemgroup== METConstants::taxGroupGSTFree || _taxItemgroup == METConstants::GSTFree)
    {
        return 0;
    }

    while select custInvoiceLine
        where custInvoiceLine.Description == _description
            && custInvoiceLine.ParentRecId == _custInvoiceTable.RecId
    {
        summedGSTTaxAmount += Tax::calcTaxAmount(custInvoiceLine.TaxGroup, custInvoiceLine.TaxItemGroup, _custInvoiceTable.invoiceDate,
                                                _custInvoiceTable.CurrencyCode, custInvoiceLine.AmountCur, TaxModuleType::FreeTxtInvoice);
    }

    return summedGSTTaxAmount;
}
